//! 🖼️ IDML embedded raster contents preserve actual firstparty PNG/JPEG bytes.
use super::*;
use semio_s_artifact_layout_layout_model::ImageLink;
fn encoded(node:XmlNode)->Result<Vec<u8>,String>{xml_document_to_text_checked(&XmlDocument{root:Some(node),..XmlDocument::default()}).map(String::into_bytes)}
fn opening(node:XmlNode)->Result<Vec<u8>,String>{let mut bytes=encoded(node)?;if !bytes.ends_with(b"/>"){return Err("layout.idml.xml-open".into());}bytes.truncate(bytes.len()-2);bytes.push(b'>');Ok(bytes)}
fn data<'a>(doc:&'a LayoutSnapshot,frame:&Frame)->Result<(&'a ImageLink,Option<&'a str>,&'static str),String>{let Frame::Image{link_id,..}=frame else{return Err("layout.idml.image-frame".into())};let link=doc.links.iter().find(|link|&link.id==link_id).ok_or("layout.idml.missing-image-link")?;let (payload,format)=if let Some(source)=link.proxy_data_url.as_deref(){let(header,payload)=source.split_once(',').ok_or("layout.idml.image-data-url")?;let format=match header{"data:image/png;base64"=>"$ID/Portable Network Graphics (PNG)","data:image/jpeg;base64"=>"$ID/JPEG",_=>return Err("layout.idml.image-codec".into())};(Some(payload),format)}else{let format=if link.artifact_kind=="s.stdio.png"||link.path.to_ascii_lowercase().ends_with(".png"){"$ID/Portable Network Graphics (PNG)"}else if link.artifact_kind=="s.stdio.jpeg"||link.path.to_ascii_lowercase().ends_with(".jpg")||link.path.to_ascii_lowercase().ends_with(".jpeg"){"$ID/JPEG"}else{return Err("layout.idml.image-codec".into())};(None,format)};if link.width==0||link.height==0||link.dpi==0||payload.is_some_and(|payload|payload.len()>MAX_INTERCHANGE_BYTES){return Err("layout.idml.image-envelope".into());}Ok((link,payload,format))}
pub(crate) fn payload<'a>(doc:&'a LayoutSnapshot,frame:&Frame)->Result<&'a str,String>{Ok(data(doc,frame)?.1.unwrap_or(""))}
fn graphic(doc:&LayoutSnapshot,frame:&Frame,id:&str)->Result<XmlNode,String>{let(link,payload,format)=data(doc,frame)?;let b=frame.bounds();let width=f64::from(link.width)*72.0/f64::from(link.dpi);let height=f64::from(link.height)*72.0/f64::from(link.dpi);Ok(element("Image",vec![("Self",format!("{id}-graphic")),("ImageTypeName",format.into()),("ActualPpi",format!("{} {}",link.dpi,link.dpi)),("EffectivePpi",format!("{} {}",f64::from(link.width)*72.0/b.width,f64::from(link.height)*72.0/b.height)),("ItemTransform",format!("{} 0 0 {} 0 0",b.width/width,b.height/height)),("Visible","true".into())],vec![element("Properties",Vec::new(),vec![element("GraphicBounds",vec![("Left","0".into()),("Top","0".into()),("Right",width.to_string()),("Bottom",height.to_string())],Vec::new()),element("Label",Vec::new(),vec![element("KeyValuePair",vec![("Key","semio:image-link".into()),("Value",link.id.clone())],Vec::new())])]),element("Link",vec![("Self",format!("{id}-link")),("LinkResourceURI",format!("file:{}",link.path)),("LinkResourceFormat",format.into()),("StoredState",if payload.is_some(){"Embedded"}else{"Normal"}.into()),("LinkClassID","35906".into()),("LinkClientID","257".into()),("CanEmbed","true".into()),("CanUnembed","true".into())],Vec::new())]))}
pub(crate) fn attach(doc:&LayoutSnapshot,frame:&Frame,node:&mut XmlNode)->Result<(),String>{let(_,payload,_)=data(doc,frame)?;if payload.is_some_and(|payload|payload.bytes().any(|byte|!byte.is_ascii_alphanumeric()&&!b"+/=".contains(&byte))){return Err("layout.idml.image-base64".into());}let mut image=graphic(doc,frame,&identity(node)?)?;let XmlNode::Element{children:parts,..}=&mut image else{unreachable!()};let XmlNode::Element{children:properties,..}=&mut parts[0]else{unreachable!()};if let Some(payload)=payload{properties.insert(0,element("Contents",Vec::new(),vec![XmlNode::Text{text:payload.into()}]));}let XmlNode::Element{children,..}=node else{unreachable!()};children.push(image);Ok(())}
pub(crate) fn export_parts<'a>(doc:&'a LayoutSnapshot,frame:&Frame,x:f64)->Result<(Vec<u8>,&'a str,Vec<u8>),String>{export_parts_from_node(doc,frame,frame_node_at(doc,frame,x)?)}
pub(crate) fn export_parts_from_node<'a>(doc:&'a LayoutSnapshot,frame:&Frame,mut node:XmlNode)->Result<(Vec<u8>,&'a str,Vec<u8>),String>{
    let(_,payload,_)=data(doc,frame)?;if payload.is_none(){attach(doc,frame,&mut node)?;return Ok((encoded(node)?,"",Vec::new()));}let payload=payload.unwrap();let id=identity(&node)?;let XmlNode::Element{name,attrs,children}=node else{unreachable!()};let mut prefix=opening(XmlNode::Element{name,attrs,children:Vec::new()})?;for child in children{prefix.extend(encoded(child)?);}
    let XmlNode::Element{name,attrs,children}=graphic(doc,frame,&id)? else{unreachable!()};prefix.extend(opening(XmlNode::Element{name,attrs,children:Vec::new()})?);prefix.extend(b"<Properties><Contents>");let mut suffix=b"</Contents>".to_vec();
    for child in children{if let XmlNode::Element{name,children,..}=&child{if name=="Properties"{for property in children{suffix.extend(encoded(property.clone())?);}suffix.extend(b"</Properties>");continue;}}suffix.extend(encoded(child)?);}suffix.extend(b"</Image></Rectangle>");Ok((prefix,payload,suffix))
}
pub(super) fn import(doc:&mut LayoutSnapshot,source:&XmlNode)->Result<String,String>{
    let link=nodes(source,"Link")?.first().copied();let labels=nodes(source,"KeyValuePair")?.into_iter().filter(|node|attr(node,"Key")==Some("semio:image-link")).collect::<Vec<_>>();if labels.len()>1{return Err("layout.idml.image-link-label".into());}let id=labels.first().and_then(|node|attr(node,"Value")).map(str::to_string).or(link.map(identity).transpose()?).unwrap_or_else(||format!("image-{}",doc.links.len()+1));
    let uri=link.and_then(|link|attr(link,"LinkResourceURI")).unwrap_or("");let path=uri.strip_prefix("file:").unwrap_or(uri).to_string();let contents=nodes(source,"Contents")?.first().copied();let mut proxy=None;let mut width=1;let mut height=1;let format=link.and_then(|link|attr(link,"LinkResourceFormat")).or_else(||attr(source,"ImageTypeName")).unwrap_or("");let mut kind=if format.contains("PNG"){"s.stdio.png"}else if format.contains("JPEG"){"s.stdio.jpeg"}else{""}.to_string();
    let dpi=attr(source,"ActualPpi").map(|value|numbers(value,2)).transpose()?.map_or(72.0,|values|values[0]).round().clamp(1.0,9600.0)as u32;
    if let Some(contents)=contents{let mut payload=String::new();text(contents,&mut payload);payload.retain(|character|!character.is_ascii_whitespace());let bytes=store::pack_rt::pack_value_from_base64(&payload).map_err(|error|error.to_string())?;if bytes.len()>MAX_INTERCHANGE_BYTES{return Err("layout.interchange.byte-limit".into());}let mime=if bytes.starts_with(b"\x89PNG\r\n\x1a\n"){if bytes.len()<24{return Err("layout.idml.png-header".into());}let w=u32::from_be_bytes(bytes[16..20].try_into().map_err(|_|"layout.idml.png-header")?);let h=u32::from_be_bytes(bytes[20..24].try_into().map_err(|_|"layout.idml.png-header")?);if u64::from(w)*u64::from(h)>4_194_304{return Err("layout.idml.image-pixel-limit".into());}let png=semio_s_artifact_stdio_png::standards::v1_2::subsets::any::io::project_png(&bytes)?;width=png.width;height=png.height;kind="s.stdio.png".into();"image/png"}else if bytes.starts_with(&[255,216,255]){kind="s.stdio.jpeg".into();"image/jpeg"}else{return Err("layout.idml.image-codec".into())};proxy=Some(format!("data:{mime};base64,{}",store::pack_rt::pack_value_to_base64(&bytes)));}
    if let Some(bounds)=nodes(source,"GraphicBounds")?.first(){let left=attr(bounds,"Left").unwrap_or("0").parse::<f64>().map_err(|_|"layout.idml.graphic-bounds")?;let top=attr(bounds,"Top").unwrap_or("0").parse::<f64>().map_err(|_|"layout.idml.graphic-bounds")?;let right=attr(bounds,"Right").unwrap_or("1").parse::<f64>().map_err(|_|"layout.idml.graphic-bounds")?;let bottom=attr(bounds,"Bottom").unwrap_or("1").parse::<f64>().map_err(|_|"layout.idml.graphic-bounds")?;if kind!="s.stdio.png"||proxy.is_none(){width=((right-left)*f64::from(dpi)/72.0).round().max(1.0)as u32;height=((bottom-top)*f64::from(dpi)/72.0).round().max(1.0)as u32;}}
    let value=ImageLink{id:id.clone(),path,hash:String::new(),width,height,dpi,color_profile:None,state:Some(if proxy.is_some(){"ok"}else{"missing"}.into()),proxy_data_url:proxy,artifact_kind:kind,artifact_ref:String::new()};if let Some(existing)=doc.links.iter().find(|link|link.id==id){if existing!=&value{return Err("layout.idml.conflicting-image-link".into());}}else{doc.links.push(value);}Ok(id)
}
